-- 0041  ESS validation moves to the SmartDocFlow eInvoicing Services API.
--
-- On 7 October 2026 the client withdrew the ESS validation host and developer
-- guide it had sent that morning (services.ebusiness-cloud.com, OAuth 2.0
-- client credentials) and named SmartDocFlow, ESS's e-invoicing service, in
-- its place: the testing tool https://demo-api.staging.smartdocflow.com/ and
-- the SmartDocFlow eInvoicing Services API 2.0.0, whose OpenAPI 3.0.1 document
-- is published on SwaggerHub:
--
--   https://api.swaggerhub.com/apis/ebusinesssoftwareser/smartdocflow-services/2.0.0/swagger.json
--   sha256 a3046ea93698b7788f16238a7f54bd5ae21951592026c6b238669ea3077b6c9a (read 7 Oct 2026)
--
-- The API splits validation by rule set. Two operations are recorded:
--
--   * the existing ESS record (10feb4e1-16d8-4f67-8463-99d44565580d) becomes
--     POST /peppol/aunz/validate/ubl: UBL XSD plus the Peppol PINT A-NZ rule
--     packs (1.1.3, billing and self-billing), the Australian rules the client
--     asked for. Its old schemas, read from the withdrawn host's document, are
--     replaced by the new document's;
--   * a new record for POST /schematron/ubl with profile ubl-en16931: the
--     EN 16931 rules. The group's invoices (beliq output, Peppol BIS Billing
--     3.0) are EN 16931 documents, not PINT A-NZ ones, so this is the
--     operation the composed processes can use.
--
-- Rows were built with the importer's own code (detect, parseOpenApi3,
-- toApiRow, extractDocumentSchemas, toSchemaRows, toFieldRows,
-- toParameterRows), as a Publisher import would store them; the importer only
-- inserts, so it cannot rebuild an existing record. The endpoints are the
-- staging host the client gave; /schematron/{format} is fixed to ubl, so its
-- format path parameter is not stored.
--
-- Both operations were called on the staging host on 7 October 2026: the
-- group's invoice CS95-B2B-0001 passed EN 16931 (and failed BR-CO-16 once its
-- payable amount was altered); the official PINT A-NZ "AU Invoice" and
-- "AU Credit note" examples passed all three PINT A-NZ checks. Both records are
-- left Published for an administrator to verify in the application.

-- ----------------------------------------------------------------- preconditions

create temporary table _0041_api on commit drop as
select * from jsonb_populate_recordset(null::public.apis, $rows0041$[{"api_name": "ESS SmartDocFlow Validate PINT A-NZ Invoice API", "official_api_name": "Validate a Peppol PINT A-NZ invoice (Invoice root) against the UBL XSD and the PINT rule packs.", "description": "Runs the Peppol PINT Australia / New Zealand compliance checks on a UBL invoice whose root element is Invoice (including one with credit-note type code 381), sent base64-encoded in content. Three checks run in order: the UBL 2.1 Invoice XSD, the PINT shared rules (170 asserts) and the A-NZ jurisdiction-aligned rules (74 asserts). The pack (billing or selfbilling) is detected from cbc:CustomizationID or declared in pack; checks may be limited to a subset. Every assert is fatal: the call returns 200 only when every check passes, otherwise each failing check with the OpenPeppol rule ids and messages.", "api_endpoint": "https://xml.staging.smartdocflow.com/v1/peppol/aunz/validate/ubl", "company_name": "EB Software Services (ESS)", "company_name_original": "", "official_company_name": "", "documentation_url": "https://api.swaggerhub.com/apis/ebusinesssoftwareser/smartdocflow-services/2.0.0/swagger.json", "source_url": "https://api.swaggerhub.com/apis/ebusinesssoftwareser/smartdocflow-services/2.0.0/swagger.json", "http_method": "POST", "category": "Validation", "communication_direction": "", "authentication_method": "API Key", "authentication_other": "", "input_formats": ["JSON"], "input_formats_original": ["application/json"], "output_formats": ["JSON"], "output_formats_original": ["application/json"], "data_quality": "ok", "access_scope": "public", "review_status": "Published", "id": "10feb4e1-16d8-4f67-8463-99d44565580d", "website_url": "https://www.ebsoftwareservices.com.au/", "authentication_details": "API key in the x-api-key header. A key for the staging host is issued by entering a business e-mail address in the provider's SmartDocFlow testing tool (https://demo-api.staging.smartdocflow.com/), which e-mails it. Staging host xml.staging.smartdocflow.com/v1; the document also lists the production host xml.smartdocflow.com/v1.", "network": "", "business_rules": ["Peppol PINT A-NZ Billing 1.1.3 (urn:peppol:pint:billing-1@aunz-1)", "Peppol PINT A-NZ Self-billing 1.1.3 (urn:peppol:pint:selfbilling-1@aunz-1)", "OASIS UBL 2.1 Invoice XSD"], "invoice_standard": ["Peppol PINT A-NZ 1.1.3", "UBL 2.1"], "invoice_standard_source": "confirmed"}, {"api_name": "ESS SmartDocFlow Validate EN 16931 UBL Invoice API", "official_api_name": "Validate against the European EN16931 Schematron (or the Factur-X profile-specific rules).", "description": "Validates a UBL 2.1 invoice, sent base64-encoded in content, against the EN 16931 UBL Schematron V1.3.16 (profile ubl-en16931). The request must name the profile; the same endpoint also applies the French Flux 2 (ubl-flux2) and AFNOR EXTENDED-CTC-FR (ubl-extended-ctc-fr) overlays. Returns success, or each fired rule with its id, severity, location and test.", "api_endpoint": "https://xml.staging.smartdocflow.com/v1/schematron/ubl", "company_name": "EB Software Services (ESS)", "company_name_original": "", "official_company_name": "", "documentation_url": "https://api.swaggerhub.com/apis/ebusinesssoftwareser/smartdocflow-services/2.0.0/swagger.json", "source_url": "https://api.swaggerhub.com/apis/ebusinesssoftwareser/smartdocflow-services/2.0.0/swagger.json", "http_method": "POST", "category": "Validation", "communication_direction": "", "authentication_method": "API Key", "authentication_other": "", "input_formats": ["JSON"], "input_formats_original": ["application/json"], "output_formats": ["JSON"], "output_formats_original": ["application/json"], "data_quality": "ok", "access_scope": "public", "review_status": "Published", "id": "0998d981-91d4-4eab-b952-0a0ec39d19be", "website_url": "https://www.ebsoftwareservices.com.au/", "authentication_details": "API key in the x-api-key header. A key for the staging host is issued by entering a business e-mail address in the provider's SmartDocFlow testing tool (https://demo-api.staging.smartdocflow.com/), which e-mails it. Staging host xml.staging.smartdocflow.com/v1; the document also lists the production host xml.smartdocflow.com/v1.", "network": "", "business_rules": ["EN 16931 UBL Schematron V1.3.16 (profile ubl-en16931)", "FR Flux 2 (FNFE) UBL overlay (profile ubl-flux2)", "AFNOR EXTENDED-CTC-FR FNFE RFE 1.4.0.04 (profile ubl-extended-ctc-fr)"], "invoice_standard": ["EN 16931", "UBL 2.1"], "invoice_standard_source": "confirmed"}]$rows0041$::jsonb);

do $$
begin
  if not exists (
    select 1 from public.apis
     where id = '10feb4e1-16d8-4f67-8463-99d44565580d'
       and api_endpoint = 'https://services.ebusiness-cloud.com/ess-schematron/v1/api/validate'
       and review_status = 'Published' and is_active and duplicate_of is null
  ) then
    raise exception '0041 precondition failed: the ESS record changed since 7 October.';
  end if;
  if exists (
    select 1 from public.apis api join _0041_api new_api
      on api.api_endpoint = new_api.api_endpoint and api.http_method = new_api.http_method
     where api.id <> '10feb4e1-16d8-4f67-8463-99d44565580d'
  ) then
    raise exception '0041 precondition failed: a SmartDocFlow operation is already recorded.';
  end if;
end
$$;

