insert into public.api_schema (id, api_id, direction, media_type, status_code, origin, source_url, content_hash, raw, warnings, created_by)
select id, api_id, direction, media_type, status_code, origin, source_url, content_hash, raw, warnings, created_by
  from jsonb_populate_recordset(null::public.api_schema, $schemas0041$[{"id": "dec99b27-885f-480b-85e9-05c4169c2672", "api_id": "10feb4e1-16d8-4f67-8463-99d44565580d", "direction": "request", "media_type": "application/json", "status_code": null, "origin": "extracted", "source_url": "https://api.swaggerhub.com/apis/ebusinesssoftwareser/smartdocflow-services/2.0.0/swagger.json", "content_hash": "8bd101a27ff8d2932427a14648d3d2eb00654e0bdd5e9784d9ae6e8252e60707", "raw": {"allOf": [{"description": "A file source — either an S3 location or inline base64 content.", "oneOf": [{"type": "object", "description": "Reference to a file in S3. Use for payloads >2 MB.", "properties": {"bucket": {"type": "string", "description": "The S3 bucket name. The API role must have read access.", "example": "my-xml-bucket"}, "key": {"type": "string", "description": "The S3 object key.", "example": "invoices/2026-05-12_invoice.xml"}}, "required": ["bucket", "key"]}, {"type": "object", "description": "Inline file content as base64. Convenient for small payloads (≤10 MB).", "properties": {"filename": {"type": "string", "description": "The original file name (used in logs and downloaded output).", "example": "invoice.xml"}, "content": {"type": "string", "format": "base64", "description": "Base64-encoded file content."}}, "required": ["filename", "content"]}]}, {"type": "object", "description": "Peppol PINT A-NZ validation directives. Both fields are optional;\nthe defaults (auto-detect the pack, run every check) are the\ncommon case and need no client logic.\n", "properties": {"pack": {"type": "string", "enum": ["billing", "selfbilling"], "description": "Which PINT A-NZ specialisation to validate against.\n\nOmit it and the server detects the pack from the document's\n`cbc:CustomizationID` (the same `starts-with` test the packs'\nown identity rules use); `details.pack_source` then reads\n`\"detected\"`.\n\nSupply it and it is an **assertion that wins**: the declared\npack runs even if the document identifies as the other one —\nwhich is what a Peppol access point would report — and the\nresponse adds `details.pack_mismatch` naming both sides so\nnobody has to decode the identity rule ids by hand.\n\nDetection is only attempted when a Schematron check is\nrequested. With `checks: [\"xsd\"]` no pack is needed and\n`details.pack_source` is `\"not_required\"`.\n\nA document with no recognisable `cbc:CustomizationID` and no\n`pack` is rejected with `400` / `PACK_REQUIRED` rather than\nguessed at — guessing produces a wall of identity failures\nthat hides the real problem.\n", "example": "billing"}, "checks": {"type": "array", "description": "Which checks to run. Omit for all three. Set semantics: the\nserver runs the requested checks in the canonical order\n`xsd` → `pint-shared` → `pint-aligned` whatever order they\nwere sent in, and echoes the effective list in\n`details.checks`, so a partial run is explicit in the\nresponse. An empty list, or any unrecognised id, is `400` /\n`CHECK_UNKNOWN`.\n", "items": {"type": "string", "enum": ["xsd", "pint-shared", "pint-aligned"]}, "example": ["xsd", "pint-shared", "pint-aligned"]}, "pack_version": {"type": "string", "description": "**Reserved — sending this field returns `400` /\n`FIELD_RESERVED`.** The deployed image ships exactly one pack\nversion, which the response always states in\n`details.pack_version` and per step in `artifact.version`.\nThe field is rejected rather than ignored so that giving it\nmeaning later is a non-breaking change.\n", "readOnly": true}}}]}, "warnings": [], "created_by": ""}, {"id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2", "api_id": "10feb4e1-16d8-4f67-8463-99d44565580d", "direction": "response", "media_type": "application/json", "status_code": "200", "origin": "extracted", "source_url": "https://api.swaggerhub.com/apis/ebusinesssoftwareser/smartdocflow-services/2.0.0/swagger.json", "content_hash": "f856fe5f004db4eb4c28baf301089e5eb7a06b9c2428ddbbe28f54ebfec1e890", "raw": {"type": "object", "description": "Peppol PINT A-NZ validation result. The envelope is the house\n`status` / `summary` / `details` shape; `details.steps[]` always\ncarries one entry per check that ran, in canonical order, with\nthe same step shape whether one check ran or three.\n\nHTTP **200** if and only if every step succeeded; any fatal\nfailure makes the whole call **400** with the same body shape.\n", "properties": {"status": {"type": "string", "enum": ["success", "error"], "example": "success"}, "summary": {"type": "string", "example": "Peppol PINT A-NZ billing: 3 of 3 checks passed."}, "details": {"type": "object", "properties": {"jurisdiction": {"type": "string", "description": "The Peppol specialisation family, echoing the path segment.", "example": "aunz"}, "format": {"type": "string", "enum": ["ubl", "ubl-creditnote"], "description": "The document root the route covers — `ubl` for `<Invoice>`, `ubl-creditnote` for `<CreditNote>`. Not the type code.", "example": "ubl"}, "pack": {"type": "string", "nullable": true, "enum": ["billing", "selfbilling", null], "description": "The pack that ran. `null` when no Schematron check was requested.", "example": "billing"}, "pack_source": {"type": "string", "enum": ["detected", "declared", "not_required"], "description": "How `pack` was arrived at: read from the document, taken from the request, or not needed (`checks: [\"xsd\"]`).", "example": "detected"}, "pack_version": {"type": "string", "description": "The PINT A-NZ pack version the deployed image ships. Always stated, even when no Schematron check ran.", "example": "1.1.3"}, "detected": {"type": "object", "description": "What the document says about itself. Populated whenever the document was read for pack detection; the fields are `null` where the document does not carry them.", "properties": {"customization_id": {"type": "string", "nullable": true, "example": "urn:peppol:pint:billing-1@aunz-1"}, "profile_id": {"type": "string", "nullable": true, "example": "urn:peppol:bis:billing"}, "type_code": {"type": "string", "nullable": true, "description": "`cbc:InvoiceTypeCode` or `cbc:CreditNoteTypeCode`. Reported, never used for routing or pack selection.", "example": "380"}}}, "checks": {"type": "array", "items": {"type": "string", "enum": ["xsd", "pint-shared", "pint-aligned"]}, "description": "The effective check list, in canonical order — echoed so a partial run is never silent.", "example": ["xsd", "pint-shared", "pint-aligned"]}, "severity_breakdown": {"allOf": [{"type": "object", "description": "Count of failures by severity. All 3 keys are always present (0 if none).", "properties": {"fatal": {"type": "integer", "minimum": 0, "example": 3}, "warning": {"type": "integer", "minimum": 0, "example": 1}, "info": {"type": "integer", "minimum": 0, "example": 0}}, "required": ["fatal", "warning", "info"]}, {"description": "Aggregate over every step. `warning` and `info` are always 0 on these routes — the PINT packs ship no advisory severity."}]}, "pack_mismatch": {"type": "object", "description": "Present only when a declared `pack` disagrees with what the document identifies as. The declared pack still ran.", "properties": {"declared": {"type": "string", "example": "billing"}, "detected": {"type": "string", "nullable": true, "example": "selfbilling"}, "hint": {"type": "string", "example": "CustomizationID starts with urn:peppol:pint:selfbilling-1@aunz-1; re-run with pack='selfbilling' or omit pack."}}}, "steps": {"type": "array", "items": {"type": "object", "description": "One check's result. The `status` / `summary` / `details` part is\nthe sub-validation's body verbatim — byte-compatible with what\n`/validate/{format}` and `/schematron/{format}` return for the\nsame check, including the structured `failures` +\n`severity_breakdown` block. Two keys are **added**: `check` and\n`artifact`. Nothing is removed or reshaped, so a consumer that\nalready renders the shared failure shape renders these steps\nunchanged and may ignore the two additions.\n", "properties": {"check": {"type": "string", "enum": ["xsd", "pint-shared", "pint-aligned"], "description": "Which check this step is.", "example": "pint-shared"}, "artifact": {"type": "object", "description": "The exact artefact a step ran. Present on every step, so pack,\nversion and file name are never ambiguous in support: the step\nboundary *is* the artefact boundary.\n", "properties": {"file": {"type": "string", "description": "Bare file name as deployed in the API package.", "example": "PINT-jurisdiction-aligned-rules.xslt"}, "version": {"type": "string", "description": "Pack version for the Schematron artefacts; the XSD's own version for the `xsd` step. Informational — never pin client behaviour to it.", "example": "1.1.3"}, "pack": {"type": "string", "enum": ["billing", "selfbilling"], "description": "Which PINT pack the stylesheet came from. Absent on the `xsd` step — the UBL 2.1 schema is pack-independent.", "example": "billing"}, "rule_families": {"type": "array", "items": {"type": "string"}, "description": "Rule-id families this artefact emits, for triage. Absent on the `xsd` step.", "example": ["aligned-ibrp-*", "aligned-ibr-*-aunz"]}}, "required": ["file"]}, "status": {"type": "string", "enum": ["success", "error"], "description": "`success` when the check produced no failure. PINT packs carry no advisory severity — every assert is fatal — so a Schematron step is either clean or failed.", "example": "error"}, "summary": {"type": "string", "example": "Schematron validation failed with 1 fatal error(s)."}, "details": {"type": "object", "nullable": true, "description": "`null` on a clean step. On failure, the shared structured failure block.", "properties": {"profile": {"type": "string", "description": "The internal pack identifier the Schematron step ran under. Informational echo — it is not a value any request field accepts.", "example": "pint-aunz-billing"}, "errors": {"type": "array", "items": {"type": "string"}, "description": "Flat pre-formatted error strings (legacy / backward-compat)."}, "failures": {"type": "array", "items": {"type": "object", "description": "A single validation failure entry. All 5 keys are always present (`null` where the source has no value for that key) so consumers can render without null-guards.", "properties": {"rule": {"type": "string", "nullable": true, "description": "Schematron assertion id (`failed-assert/@id`), or `null` for XSD errors and other formats without rule ids.", "example": "BR-CO-15"}, "severity": {"type": "string", "enum": ["fatal", "warning", "info"], "description": "Severity level. XSD errors are always `fatal`. For Schematron, mapped from `@flag` (with `@role` fallback); unrecognized / absent values default to `fatal`.", "example": "fatal"}, "location": {"type": "string", "nullable": true, "description": "Where the failure occurred. For Schematron: the XPath of the failing element (`@location` on `failed-assert`). For XSD: `\"Line N: <xpath>\"` or `\"Line N\"` or the path alone, depending on what's available.", "example": "/rsm:CrossIndustryInvoice/rsm:SupplyChainTradeTransaction"}, "test": {"type": "string", "nullable": true, "description": "For Schematron: the assertion's `@test` XPath expression. `null` for XSD.", "example": "exists(ram:InvoiceLine)"}, "message": {"type": "string", "description": "Human-readable failure message, verbatim from the rule pack. On the French-reform routes Schematron messages are in **French**; on the Peppol PINT routes they are in **English** (see info.description).", "example": "[BR-CO-15] Invoice total amount with VAT must equal the sum of the line totals..."}}, "required": ["rule", "severity", "location", "test", "message"]}}, "severity_breakdown": {"type": "object", "description": "Count of failures by severity. All 3 keys are always present (0 if none).", "properties": {"fatal": {"type": "integer", "minimum": 0, "example": 3}, "warning": {"type": "integer", "minimum": 0, "example": 1}, "info": {"type": "integer", "minimum": 0, "example": 0}}, "required": ["fatal", "warning", "info"]}}}}, "required": ["check", "artifact", "status", "summary"]}}}, "required": ["jurisdiction", "format", "pack", "pack_source", "pack_version", "checks", "severity_breakdown", "steps"]}}, "required": ["status", "summary", "details"]}, "warnings": [], "created_by": ""}, {"id": "4a315479-fa93-4593-b943-18c4a80c6a84", "api_id": "10feb4e1-16d8-4f67-8463-99d44565580d", "direction": "response", "media_type": "application/json", "status_code": "400", "origin": "extracted", "source_url": "https://api.swaggerhub.com/apis/ebusinesssoftwareser/smartdocflow-services/2.0.0/swagger.json", "content_hash": "2af4ed9e71f1249785d579aeba1ce0c7a803a0baf1a77564937c5904d67f790d", "raw": {"oneOf": [{"type": "object", "description": "Peppol PINT A-NZ validation result. The envelope is the house\n`status` / `summary` / `details` shape; `details.steps[]` always\ncarries one entry per check that ran, in canonical order, with\nthe same step shape whether one check ran or three.\n\nHTTP **200** if and only if every step succeeded; any fatal\nfailure makes the whole call **400** with the same body shape.\n", "properties": {"status": {"type": "string", "enum": ["success", "error"], "example": "success"}, "summary": {"type": "string", "example": "Peppol PINT A-NZ billing: 3 of 3 checks passed."}, "details": {"type": "object", "properties": {"jurisdiction": {"type": "string", "description": "The Peppol specialisation family, echoing the path segment.", "example": "aunz"}, "format": {"type": "string", "enum": ["ubl", "ubl-creditnote"], "description": "The document root the route covers — `ubl` for `<Invoice>`, `ubl-creditnote` for `<CreditNote>`. Not the type code.", "example": "ubl"}, "pack": {"type": "string", "nullable": true, "enum": ["billing", "selfbilling", null], "description": "The pack that ran. `null` when no Schematron check was requested.", "example": "billing"}, "pack_source": {"type": "string", "enum": ["detected", "declared", "not_required"], "description": "How `pack` was arrived at: read from the document, taken from the request, or not needed (`checks: [\"xsd\"]`).", "example": "detected"}, "pack_version": {"type": "string", "description": "The PINT A-NZ pack version the deployed image ships. Always stated, even when no Schematron check ran.", "example": "1.1.3"}, "detected": {"type": "object", "description": "What the document says about itself. Populated whenever the document was read for pack detection; the fields are `null` where the document does not carry them.", "properties": {"customization_id": {"type": "string", "nullable": true, "example": "urn:peppol:pint:billing-1@aunz-1"}, "profile_id": {"type": "string", "nullable": true, "example": "urn:peppol:bis:billing"}, "type_code": {"type": "string", "nullable": true, "description": "`cbc:InvoiceTypeCode` or `cbc:CreditNoteTypeCode`. Reported, never used for routing or pack selection.", "example": "380"}}}, "checks": {"type": "array", "items": {"type": "string", "enum": ["xsd", "pint-shared", "pint-aligned"]}, "description": "The effective check list, in canonical order — echoed so a partial run is never silent.", "example": ["xsd", "pint-shared", "pint-aligned"]}, "severity_breakdown": {"allOf": [{"type": "object", "description": "Count of failures by severity. All 3 keys are always present (0 if none).", "properties": {"fatal": {"type": "integer", "minimum": 0, "example": 3}, "warning": {"type": "integer", "minimum": 0, "example": 1}, "info": {"type": "integer", "minimum": 0, "example": 0}}, "required": ["fatal", "warning", "info"]}, {"description": "Aggregate over every step. `warning` and `info` are always 0 on these routes — the PINT packs ship no advisory severity."}]}, "pack_mismatch": {"type": "object", "description": "Present only when a declared `pack` disagrees with what the document identifies as. The declared pack still ran.", "properties": {"declared": {"type": "string", "example": "billing"}, "detected": {"type": "string", "nullable": true, "example": "selfbilling"}, "hint": {"type": "string", "example": "CustomizationID starts with urn:peppol:pint:selfbilling-1@aunz-1; re-run with pack='selfbilling' or omit pack."}}}, "steps": {"type": "array", "items": {"type": "object", "description": "One check's result. The `status` / `summary` / `details` part is\nthe sub-validation's body verbatim — byte-compatible with what\n`/validate/{format}` and `/schematron/{format}` return for the\nsame check, including the structured `failures` +\n`severity_breakdown` block. Two keys are **added**: `check` and\n`artifact`. Nothing is removed or reshaped, so a consumer that\nalready renders the shared failure shape renders these steps\nunchanged and may ignore the two additions.\n", "properties": {"check": {"type": "string", "enum": ["xsd", "pint-shared", "pint-aligned"], "description": "Which check this step is.", "example": "pint-shared"}, "artifact": {"type": "object", "description": "The exact artefact a step ran. Present on every step, so pack,\nversion and file name are never ambiguous in support: the step\nboundary *is* the artefact boundary.\n", "properties": {"file": {"type": "string", "description": "Bare file name as deployed in the API package.", "example": "PINT-jurisdiction-aligned-rules.xslt"}, "version": {"type": "string", "description": "Pack version for the Schematron artefacts; the XSD's own version for the `xsd` step. Informational — never pin client behaviour to it.", "example": "1.1.3"}, "pack": {"type": "string", "enum": ["billing", "selfbilling"], "description": "Which PINT pack the stylesheet came from. Absent on the `xsd` step — the UBL 2.1 schema is pack-independent.", "example": "billing"}, "rule_families": {"type": "array", "items": {"type": "string"}, "description": "Rule-id families this artefact emits, for triage. Absent on the `xsd` step.", "example": ["aligned-ibrp-*", "aligned-ibr-*-aunz"]}}, "required": ["file"]}, "status": {"type": "string", "enum": ["success", "error"], "description": "`success` when the check produced no failure. PINT packs carry no advisory severity — every assert is fatal — so a Schematron step is either clean or failed.", "example": "error"}, "summary": {"type": "string", "example": "Schematron validation failed with 1 fatal error(s)."}, "details": {"type": "object", "nullable": true, "description": "`null` on a clean step. On failure, the shared structured failure block.", "properties": {"profile": {"type": "string", "description": "The internal pack identifier the Schematron step ran under. Informational echo — it is not a value any request field accepts.", "example": "pint-aunz-billing"}, "errors": {"type": "array", "items": {"type": "string"}, "description": "Flat pre-formatted error strings (legacy / backward-compat)."}, "failures": {"type": "array", "items": {"type": "object", "description": "A single validation failure entry. All 5 keys are always present (`null` where the source has no value for that key) so consumers can render without null-guards.", "properties": {"rule": {"type": "string", "nullable": true, "description": "Schematron assertion id (`failed-assert/@id`), or `null` for XSD errors and other formats without rule ids.", "example": "BR-CO-15"}, "severity": {"type": "string", "enum": ["fatal", "warning", "info"], "description": "Severity level. XSD errors are always `fatal`. For Schematron, mapped from `@flag` (with `@role` fallback); unrecognized / absent values default to `fatal`.", "example": "fatal"}, "location": {"type": "string", "nullable": true, "description": "Where the failure occurred. For Schematron: the XPath of the failing element (`@location` on `failed-assert`). For XSD: `\"Line N: <xpath>\"` or `\"Line N\"` or the path alone, depending on what's available.", "example": "/rsm:CrossIndustryInvoice/rsm:SupplyChainTradeTransaction"}, "test": {"type": "string", "nullable": true, "description": "For Schematron: the assertion's `@test` XPath expression. `null` for XSD.", "example": "exists(ram:InvoiceLine)"}, "message": {"type": "string", "description": "Human-readable failure message, verbatim from the rule pack. On the French-reform routes Schematron messages are in **French**; on the Peppol PINT routes they are in **English** (see info.description).", "example": "[BR-CO-15] Invoice total amount with VAT must equal the sum of the line totals..."}}, "required": ["rule", "severity", "location", "test", "message"]}}, "severity_breakdown": {"type": "object", "description": "Count of failures by severity. All 3 keys are always present (0 if none).", "properties": {"fatal": {"type": "integer", "minimum": 0, "example": 3}, "warning": {"type": "integer", "minimum": 0, "example": 1}, "info": {"type": "integer", "minimum": 0, "example": 0}}, "required": ["fatal", "warning", "info"]}}}}, "required": ["check", "artifact", "status", "summary"]}}}, "required": ["jurisdiction", "format", "pack", "pack_source", "pack_version", "checks", "severity_breakdown", "steps"]}}, "required": ["status", "summary", "details"]}, {"type": "object", "description": "A **request-level** rejection on a `/peppol/…` route: the request\nitself could not be honoured, so no check ran and `details.steps`\nis absent. `details.code` names the reason from a closed set, and\nthe matching `allowed_*` list tells the client exactly what to\nsend instead.\n\nThis shape is specific to the Peppol routes. Validation failures\n(rules that fired) keep the normal steps response, also with\nstatus `400`.\n", "properties": {"status": {"type": "string", "example": "error"}, "summary": {"type": "string", "example": "Unable to determine the Peppol PINT A-NZ pack; declare it with 'pack'."}, "details": {"type": "object", "properties": {"code": {"type": "string", "enum": ["PACK_REQUIRED", "PACK_UNKNOWN", "CHECK_UNKNOWN", "FIELD_RESERVED"], "description": "Why the request was rejected:\n\n- `PACK_REQUIRED` — a Schematron check was requested, the\n  document carries no recognisable `cbc:CustomizationID`,\n  and no `pack` was declared. `details.detected` and\n  `details.allowed_packs` are present.\n- `PACK_UNKNOWN` — the `pack` value is not one this\n  jurisdiction publishes. `details.allowed_packs` is present.\n- `CHECK_UNKNOWN` — `checks` was empty, or contained an id\n  that is not a check. `details.allowed_checks` is present.\n- `FIELD_RESERVED` — the request carried a reserved field\n  (today: `pack_version`). `details.field` names it.\n", "example": "PACK_REQUIRED"}, "field": {"type": "string", "description": "Present with `FIELD_RESERVED` — the reserved field the request sent.", "example": "pack_version"}, "allowed_packs": {"type": "array", "items": {"type": "string"}, "example": ["billing", "selfbilling"]}, "allowed_checks": {"type": "array", "items": {"type": "string"}, "example": ["xsd", "pint-shared", "pint-aligned"]}, "detected": {"type": "object", "description": "What the document says about itself. Populated whenever the document was read for pack detection; the fields are `null` where the document does not carry them.", "properties": {"customization_id": {"type": "string", "nullable": true, "example": "urn:peppol:pint:billing-1@aunz-1"}, "profile_id": {"type": "string", "nullable": true, "example": "urn:peppol:bis:billing"}, "type_code": {"type": "string", "nullable": true, "description": "`cbc:InvoiceTypeCode` or `cbc:CreditNoteTypeCode`. Reported, never used for routing or pack selection.", "example": "380"}}}}, "required": ["code"]}}, "required": ["status", "summary", "details"]}]}, "warnings": ["oneOf/anyOf at (root) states alternatives; its branches are not flattened"], "created_by": ""}, {"id": "cdf70ba1-7a87-46cf-a155-e4ffeda9fc7a", "api_id": "10feb4e1-16d8-4f67-8463-99d44565580d", "direction": "response", "media_type": "application/json", "status_code": "404", "origin": "extracted", "source_url": "https://api.swaggerhub.com/apis/ebusinesssoftwareser/smartdocflow-services/2.0.0/swagger.json", "content_hash": "e29302ee8d249f1383d6ce5aee24b289b94dcfe0cb64efc43d94c17e928d5a3d", "raw": {"type": "object", "description": "The shared error envelope when `details` is opaque (e.g. malformed-request errors).", "properties": {"status": {"type": "string", "example": "error"}, "summary": {"type": "string", "example": "Operation failed."}, "details": {"description": "Error context — shape varies; may be a string or an object."}}, "required": ["status", "summary"]}, "warnings": [], "created_by": ""}, {"id": "8f264090-a716-4937-ad20-4012dc5e0d46", "api_id": "10feb4e1-16d8-4f67-8463-99d44565580d", "direction": "response", "media_type": "application/json", "status_code": "500", "origin": "extracted", "source_url": "https://api.swaggerhub.com/apis/ebusinesssoftwareser/smartdocflow-services/2.0.0/swagger.json", "content_hash": "e29302ee8d249f1383d6ce5aee24b289b94dcfe0cb64efc43d94c17e928d5a3d", "raw": {"type": "object", "description": "The shared error envelope when `details` is opaque (e.g. malformed-request errors).", "properties": {"status": {"type": "string", "example": "error"}, "summary": {"type": "string", "example": "Operation failed."}, "details": {"description": "Error context — shape varies; may be a string or an object."}}, "required": ["status", "summary"]}, "warnings": [], "created_by": ""}, {"id": "ce23deaf-7c8c-432b-95bf-1fd971ede855", "api_id": "0998d981-91d4-4eab-b952-0a0ec39d19be", "direction": "request", "media_type": "application/json", "status_code": null, "origin": "extracted", "source_url": "https://api.swaggerhub.com/apis/ebusinesssoftwareser/smartdocflow-services/2.0.0/swagger.json", "content_hash": "2cf30917516e8a532c38a8940ebc88182f8eec4796186e33b62c391bcba27de7", "raw": {"allOf": [{"description": "A file source — either an S3 location or inline base64 content.", "oneOf": [{"type": "object", "description": "Reference to a file in S3. Use for payloads >2 MB.", "properties": {"bucket": {"type": "string", "description": "The S3 bucket name. The API role must have read access.", "example": "my-xml-bucket"}, "key": {"type": "string", "description": "The S3 object key.", "example": "invoices/2026-05-12_invoice.xml"}}, "required": ["bucket", "key"]}, {"type": "object", "description": "Inline file content as base64. Convenient for small payloads (≤10 MB).", "properties": {"filename": {"type": "string", "description": "The original file name (used in logs and downloaded output).", "example": "invoice.xml"}, "content": {"type": "string", "format": "base64", "description": "Base64-encoded file content."}}, "required": ["filename", "content"]}]}, {"type": "object", "properties": {"profile": {"type": "string", "description": "Profile / variant of the Schematron pack to apply.\n- `factur-x`: `basicwl` | `en16931` | `extended`\n- `cii`: `cii-en16931` | `cii-flux2` | `cii-extended-ctc-fr`\n- `ubl`: `ubl-en16931` | `ubl-flux2` | `ubl-extended-ctc-fr`\n- `ubl-creditnote`: `ubl-creditnote-en16931` | `ubl-creditnote-flux2` | `ubl-creditnote-extended-ctc-fr`\n", "example": "en16931"}}, "required": ["profile"]}]}, "warnings": [], "created_by": ""}, {"id": "a80e80d3-4a6d-4b12-9c8d-900b4d845d97", "api_id": "0998d981-91d4-4eab-b952-0a0ec39d19be", "direction": "response", "media_type": "application/json", "status_code": "200", "origin": "extracted", "source_url": "https://api.swaggerhub.com/apis/ebusinesssoftwareser/smartdocflow-services/2.0.0/swagger.json", "content_hash": "9811801e699fae9c31cb32399ff75d0124f26a49aac3a990572cf30bbcef0b96", "raw": {"type": "object", "description": "The shared success envelope. `details` varies by endpoint.", "properties": {"status": {"type": "string", "enum": ["success", "warning"], "example": "success"}, "summary": {"type": "string", "description": "Human-readable result summary.", "example": "XML is valid against CII schema."}, "details": {"type": "object", "description": "Endpoint-specific payload (parsed tree, generated PDF, version info, etc.). May be omitted on plain success responses."}}, "required": ["status", "summary"]}, "warnings": [], "created_by": ""}, {"id": "50c6eea9-2b92-4d57-af7f-0245a6115bf8", "api_id": "0998d981-91d4-4eab-b952-0a0ec39d19be", "direction": "response", "media_type": "application/json", "status_code": "400", "origin": "extracted", "source_url": "https://api.swaggerhub.com/apis/ebusinesssoftwareser/smartdocflow-services/2.0.0/swagger.json", "content_hash": "102cda447d58f9f2ca9ad22242a241b0b30dcc42800b7d07200b438d4548ce7f", "raw": {"type": "object", "description": "The error envelope for `/validate/*`, `/schematron/*`, and\n`/schematron-fr/*` when validation fails. Carries three pieces:\n\n- `errors` — a flat list of pre-formatted strings, kept for\n  backward compatibility with consumers from before structured\n  failures existed. Will eventually be deprecated; new consumers\n  should read `failures`.\n- `failures` — the structured failure list (see `Failure`).\n- `severity_breakdown` — counts by severity (see\n  `SeverityBreakdown`).\n\nSome endpoints also include a `profile` field echoing the\nprofile that was validated against.\n", "properties": {"status": {"type": "string", "example": "error"}, "summary": {"type": "string", "example": "Schema Validation Failed with 3 error(s)."}, "details": {"type": "object", "properties": {"profile": {"type": "string", "description": "Echoed back on Schematron endpoints.", "example": "en16931"}, "errors": {"type": "array", "items": {"type": "string"}, "description": "Flat pre-formatted error strings (legacy / backward-compat)."}, "failures": {"type": "array", "items": {"type": "object", "description": "A single validation failure entry. All 5 keys are always present (`null` where the source has no value for that key) so consumers can render without null-guards.", "properties": {"rule": {"type": "string", "nullable": true, "description": "Schematron assertion id (`failed-assert/@id`), or `null` for XSD errors and other formats without rule ids.", "example": "BR-CO-15"}, "severity": {"type": "string", "enum": ["fatal", "warning", "info"], "description": "Severity level. XSD errors are always `fatal`. For Schematron, mapped from `@flag` (with `@role` fallback); unrecognized / absent values default to `fatal`.", "example": "fatal"}, "location": {"type": "string", "nullable": true, "description": "Where the failure occurred. For Schematron: the XPath of the failing element (`@location` on `failed-assert`). For XSD: `\"Line N: <xpath>\"` or `\"Line N\"` or the path alone, depending on what's available.", "example": "/rsm:CrossIndustryInvoice/rsm:SupplyChainTradeTransaction"}, "test": {"type": "string", "nullable": true, "description": "For Schematron: the assertion's `@test` XPath expression. `null` for XSD.", "example": "exists(ram:InvoiceLine)"}, "message": {"type": "string", "description": "Human-readable failure message, verbatim from the rule pack. On the French-reform routes Schematron messages are in **French**; on the Peppol PINT routes they are in **English** (see info.description).", "example": "[BR-CO-15] Invoice total amount with VAT must equal the sum of the line totals..."}}, "required": ["rule", "severity", "location", "test", "message"]}}, "severity_breakdown": {"type": "object", "description": "Count of failures by severity. All 3 keys are always present (0 if none).", "properties": {"fatal": {"type": "integer", "minimum": 0, "example": 3}, "warning": {"type": "integer", "minimum": 0, "example": 1}, "info": {"type": "integer", "minimum": 0, "example": 0}}, "required": ["fatal", "warning", "info"]}}, "required": ["errors", "failures", "severity_breakdown"]}}, "required": ["status", "summary", "details"]}, "warnings": [], "created_by": ""}, {"id": "d686d872-1bb5-4fac-9b15-b35739f8c829", "api_id": "0998d981-91d4-4eab-b952-0a0ec39d19be", "direction": "response", "media_type": "application/json", "status_code": "500", "origin": "extracted", "source_url": "https://api.swaggerhub.com/apis/ebusinesssoftwareser/smartdocflow-services/2.0.0/swagger.json", "content_hash": "e29302ee8d249f1383d6ce5aee24b289b94dcfe0cb64efc43d94c17e928d5a3d", "raw": {"type": "object", "description": "The shared error envelope when `details` is opaque (e.g. malformed-request errors).", "properties": {"status": {"type": "string", "example": "error"}, "summary": {"type": "string", "example": "Operation failed."}, "details": {"description": "Error context — shape varies; may be a string or an object."}}, "required": ["status", "summary"]}, "warnings": [], "created_by": ""}]$schemas0041$::jsonb);

insert into public.api_schema_field (path, leaf_name, leaf_name_norm, json_type, format, is_required, is_array_item, depth, enum_values, description, schema_id)
select path, leaf_name, leaf_name_norm, json_type, format, is_required, is_array_item, depth, enum_values, description, schema_id
  from jsonb_populate_recordset(null::public.api_schema_field, $fields0041$[{"path": "pack", "leaf_name": "pack", "leaf_name_norm": "pack", "json_type": "string", "format": null, "is_required": false, "is_array_item": false, "depth": 0, "enum_values": ["billing", "selfbilling"], "description": "Which PINT A-NZ specialisation to validate against.\n\nOmit it and the server detects the pack from the document's\n`cbc:CustomizationID` (the same `starts-with` test the packs'\nown identity rules use); `details.pack_source` then reads\n`\"detected\"`.\n\nSupply it and it is an **assertion that wins**: the declared\npack runs even if the document identifies as the other one —\nwhich is what a Peppol access point would report — and the\nresponse adds `details.pack_mismatch` naming both sides so\nnobody has to decode the identity rule ids by hand.\n\nDetection is only attempted when a Schematron check is\nrequested. With `checks: [\"xsd\"]` no pack is needed and\n`details.pack_source` is `\"not_required\"`.\n\nA document with no recognisable `cbc:CustomizationID` and no\n`pack` is rejected with `400` / `PACK_REQUIRED` rather than\nguessed at — guessing produces a wall of identity failures\nthat hides the real problem.", "schema_id": "dec99b27-885f-480b-85e9-05c4169c2672"}, {"path": "checks", "leaf_name": "checks", "leaf_name_norm": "checks", "json_type": "array", "format": null, "is_required": false, "is_array_item": false, "depth": 0, "enum_values": null, "description": "Which checks to run. Omit for all three. Set semantics: the\nserver runs the requested checks in the canonical order\n`xsd` → `pint-shared` → `pint-aligned` whatever order they\nwere sent in, and echoes the effective list in\n`details.checks`, so a partial run is explicit in the\nresponse. An empty list, or any unrecognised id, is `400` /\n`CHECK_UNKNOWN`.", "schema_id": "dec99b27-885f-480b-85e9-05c4169c2672"}, {"path": "checks[]", "leaf_name": "checks", "leaf_name_norm": "checks", "json_type": "string", "format": null, "is_required": false, "is_array_item": true, "depth": 0, "enum_values": ["xsd", "pint-shared", "pint-aligned"], "description": "", "schema_id": "dec99b27-885f-480b-85e9-05c4169c2672"}, {"path": "pack_version", "leaf_name": "pack_version", "leaf_name_norm": "packversion", "json_type": "string", "format": null, "is_required": false, "is_array_item": false, "depth": 0, "enum_values": null, "description": "**Reserved — sending this field returns `400` /\n`FIELD_RESERVED`.** The deployed image ships exactly one pack\nversion, which the response always states in\n`details.pack_version` and per step in `artifact.version`.\nThe field is rejected rather than ignored so that giving it\nmeaning later is a non-breaking change.", "schema_id": "dec99b27-885f-480b-85e9-05c4169c2672"}, {"path": "status", "leaf_name": "status", "leaf_name_norm": "status", "json_type": "string", "format": null, "is_required": true, "is_array_item": false, "depth": 0, "enum_values": ["success", "error"], "description": "", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "summary", "leaf_name": "summary", "leaf_name_norm": "summary", "json_type": "string", "format": null, "is_required": true, "is_array_item": false, "depth": 0, "enum_values": null, "description": "", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details", "leaf_name": "details", "leaf_name_norm": "details", "json_type": "object", "format": null, "is_required": true, "is_array_item": false, "depth": 0, "enum_values": null, "description": "", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.jurisdiction", "leaf_name": "jurisdiction", "leaf_name_norm": "jurisdiction", "json_type": "string", "format": null, "is_required": true, "is_array_item": false, "depth": 1, "enum_values": null, "description": "The Peppol specialisation family, echoing the path segment.", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.format", "leaf_name": "format", "leaf_name_norm": "format", "json_type": "string", "format": null, "is_required": true, "is_array_item": false, "depth": 1, "enum_values": ["ubl", "ubl-creditnote"], "description": "The document root the route covers — `ubl` for `<Invoice>`, `ubl-creditnote` for `<CreditNote>`. Not the type code.", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.pack", "leaf_name": "pack", "leaf_name_norm": "pack", "json_type": "string", "format": null, "is_required": true, "is_array_item": false, "depth": 1, "enum_values": ["billing", "selfbilling", "null"], "description": "The pack that ran. `null` when no Schematron check was requested.", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.pack_source", "leaf_name": "pack_source", "leaf_name_norm": "packsource", "json_type": "string", "format": null, "is_required": true, "is_array_item": false, "depth": 1, "enum_values": ["detected", "declared", "not_required"], "description": "How `pack` was arrived at: read from the document, taken from the request, or not needed (`checks: [\"xsd\"]`).", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.pack_version", "leaf_name": "pack_version", "leaf_name_norm": "packversion", "json_type": "string", "format": null, "is_required": true, "is_array_item": false, "depth": 1, "enum_values": null, "description": "The PINT A-NZ pack version the deployed image ships. Always stated, even when no Schematron check ran.", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.detected", "leaf_name": "detected", "leaf_name_norm": "detected", "json_type": "object", "format": null, "is_required": false, "is_array_item": false, "depth": 1, "enum_values": null, "description": "What the document says about itself. Populated whenever the document was read for pack detection; the fields are `null` where the document does not carry them.", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.detected.customization_id", "leaf_name": "customization_id", "leaf_name_norm": "customizationid", "json_type": "string", "format": null, "is_required": false, "is_array_item": false, "depth": 2, "enum_values": null, "description": "", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.detected.profile_id", "leaf_name": "profile_id", "leaf_name_norm": "profileid", "json_type": "string", "format": null, "is_required": false, "is_array_item": false, "depth": 2, "enum_values": null, "description": "", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.detected.type_code", "leaf_name": "type_code", "leaf_name_norm": "typecode", "json_type": "string", "format": null, "is_required": false, "is_array_item": false, "depth": 2, "enum_values": null, "description": "`cbc:InvoiceTypeCode` or `cbc:CreditNoteTypeCode`. Reported, never used for routing or pack selection.", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.checks", "leaf_name": "checks", "leaf_name_norm": "checks", "json_type": "array", "format": null, "is_required": true, "is_array_item": false, "depth": 1, "enum_values": null, "description": "The effective check list, in canonical order — echoed so a partial run is never silent.", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.checks[]", "leaf_name": "checks", "leaf_name_norm": "checks", "json_type": "string", "format": null, "is_required": true, "is_array_item": true, "depth": 1, "enum_values": ["xsd", "pint-shared", "pint-aligned"], "description": "", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.severity_breakdown", "leaf_name": "severity_breakdown", "leaf_name_norm": "severitybreakdown", "json_type": "object", "format": null, "is_required": true, "is_array_item": false, "depth": 1, "enum_values": null, "description": "", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.severity_breakdown.fatal", "leaf_name": "fatal", "leaf_name_norm": "fatal", "json_type": "integer", "format": null, "is_required": true, "is_array_item": false, "depth": 2, "enum_values": null, "description": "", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.severity_breakdown.warning", "leaf_name": "warning", "leaf_name_norm": "warning", "json_type": "integer", "format": null, "is_required": true, "is_array_item": false, "depth": 2, "enum_values": null, "description": "", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.severity_breakdown.info", "leaf_name": "info", "leaf_name_norm": "info", "json_type": "integer", "format": null, "is_required": true, "is_array_item": false, "depth": 2, "enum_values": null, "description": "", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.pack_mismatch", "leaf_name": "pack_mismatch", "leaf_name_norm": "packmismatch", "json_type": "object", "format": null, "is_required": false, "is_array_item": false, "depth": 1, "enum_values": null, "description": "Present only when a declared `pack` disagrees with what the document identifies as. The declared pack still ran.", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.pack_mismatch.declared", "leaf_name": "declared", "leaf_name_norm": "declared", "json_type": "string", "format": null, "is_required": false, "is_array_item": false, "depth": 2, "enum_values": null, "description": "", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.pack_mismatch.detected", "leaf_name": "detected", "leaf_name_norm": "detected", "json_type": "string", "format": null, "is_required": false, "is_array_item": false, "depth": 2, "enum_values": null, "description": "", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.pack_mismatch.hint", "leaf_name": "hint", "leaf_name_norm": "hint", "json_type": "string", "format": null, "is_required": false, "is_array_item": false, "depth": 2, "enum_values": null, "description": "", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.steps", "leaf_name": "steps", "leaf_name_norm": "steps", "json_type": "array", "format": null, "is_required": true, "is_array_item": false, "depth": 1, "enum_values": null, "description": "", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.steps[]", "leaf_name": "steps", "leaf_name_norm": "steps", "json_type": "object", "format": null, "is_required": true, "is_array_item": true, "depth": 1, "enum_values": null, "description": "One check's result. The `status` / `summary` / `details` part is\nthe sub-validation's body verbatim — byte-compatible with what\n`/validate/{format}` and `/schematron/{format}` return for the\nsame check, including the structured `failures` +\n`severity_breakdown` block. Two keys are **added**: `check` and\n`artifact`. Nothing is removed or reshaped, so a consumer that\nalready renders the shared failure shape renders these steps\nunchanged and may ignore the two additions.", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.steps[].check", "leaf_name": "check", "leaf_name_norm": "check", "json_type": "string", "format": null, "is_required": true, "is_array_item": true, "depth": 2, "enum_values": ["xsd", "pint-shared", "pint-aligned"], "description": "Which check this step is.", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.steps[].artifact", "leaf_name": "artifact", "leaf_name_norm": "artifact", "json_type": "object", "format": null, "is_required": true, "is_array_item": true, "depth": 2, "enum_values": null, "description": "The exact artefact a step ran. Present on every step, so pack,\nversion and file name are never ambiguous in support: the step\nboundary *is* the artefact boundary.", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.steps[].artifact.file", "leaf_name": "file", "leaf_name_norm": "file", "json_type": "string", "format": null, "is_required": true, "is_array_item": true, "depth": 3, "enum_values": null, "description": "Bare file name as deployed in the API package.", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.steps[].artifact.version", "leaf_name": "version", "leaf_name_norm": "version", "json_type": "string", "format": null, "is_required": false, "is_array_item": true, "depth": 3, "enum_values": null, "description": "Pack version for the Schematron artefacts; the XSD's own version for the `xsd` step. Informational — never pin client behaviour to it.", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.steps[].artifact.pack", "leaf_name": "pack", "leaf_name_norm": "pack", "json_type": "string", "format": null, "is_required": false, "is_array_item": true, "depth": 3, "enum_values": ["billing", "selfbilling"], "description": "Which PINT pack the stylesheet came from. Absent on the `xsd` step — the UBL 2.1 schema is pack-independent.", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.steps[].artifact.rule_families", "leaf_name": "rule_families", "leaf_name_norm": "rulefamilies", "json_type": "array", "format": null, "is_required": false, "is_array_item": true, "depth": 3, "enum_values": null, "description": "Rule-id families this artefact emits, for triage. Absent on the `xsd` step.", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.steps[].artifact.rule_families[]", "leaf_name": "rule_families", "leaf_name_norm": "rulefamilies", "json_type": "string", "format": null, "is_required": false, "is_array_item": true, "depth": 3, "enum_values": null, "description": "", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.steps[].status", "leaf_name": "status", "leaf_name_norm": "status", "json_type": "string", "format": null, "is_required": true, "is_array_item": true, "depth": 2, "enum_values": ["success", "error"], "description": "`success` when the check produced no failure. PINT packs carry no advisory severity — every assert is fatal — so a Schematron step is either clean or failed.", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.steps[].summary", "leaf_name": "summary", "leaf_name_norm": "summary", "json_type": "string", "format": null, "is_required": true, "is_array_item": true, "depth": 2, "enum_values": null, "description": "", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.steps[].details", "leaf_name": "details", "leaf_name_norm": "details", "json_type": "object", "format": null, "is_required": false, "is_array_item": true, "depth": 2, "enum_values": null, "description": "`null` on a clean step. On failure, the shared structured failure block.", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.steps[].details.profile", "leaf_name": "profile", "leaf_name_norm": "profile", "json_type": "string", "format": null, "is_required": false, "is_array_item": true, "depth": 3, "enum_values": null, "description": "The internal pack identifier the Schematron step ran under. Informational echo — it is not a value any request field accepts.", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.steps[].details.errors", "leaf_name": "errors", "leaf_name_norm": "errors", "json_type": "array", "format": null, "is_required": false, "is_array_item": true, "depth": 3, "enum_values": null, "description": "Flat pre-formatted error strings (legacy / backward-compat).", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.steps[].details.errors[]", "leaf_name": "errors", "leaf_name_norm": "errors", "json_type": "string", "format": null, "is_required": false, "is_array_item": true, "depth": 3, "enum_values": null, "description": "", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.steps[].details.failures", "leaf_name": "failures", "leaf_name_norm": "failures", "json_type": "array", "format": null, "is_required": false, "is_array_item": true, "depth": 3, "enum_values": null, "description": "", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.steps[].details.failures[]", "leaf_name": "failures", "leaf_name_norm": "failures", "json_type": "object", "format": null, "is_required": false, "is_array_item": true, "depth": 3, "enum_values": null, "description": "A single validation failure entry. All 5 keys are always present (`null` where the source has no value for that key) so consumers can render without null-guards.", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.steps[].details.failures[].rule", "leaf_name": "rule", "leaf_name_norm": "rule", "json_type": "string", "format": null, "is_required": true, "is_array_item": true, "depth": 4, "enum_values": null, "description": "Schematron assertion id (`failed-assert/@id`), or `null` for XSD errors and other formats without rule ids.", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.steps[].details.failures[].severity", "leaf_name": "severity", "leaf_name_norm": "severity", "json_type": "string", "format": null, "is_required": true, "is_array_item": true, "depth": 4, "enum_values": ["fatal", "warning", "info"], "description": "Severity level. XSD errors are always `fatal`. For Schematron, mapped from `@flag` (with `@role` fallback); unrecognized / absent values default to `fatal`.", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.steps[].details.failures[].location", "leaf_name": "location", "leaf_name_norm": "location", "json_type": "string", "format": null, "is_required": true, "is_array_item": true, "depth": 4, "enum_values": null, "description": "Where the failure occurred. For Schematron: the XPath of the failing element (`@location` on `failed-assert`). For XSD: `\"Line N: <xpath>\"` or `\"Line N\"` or the path alone, depending on what's available.", "schema_id": "ed4240c7-78f2-4b26-8cd1-718b652edfd2"}, {"path": "details.steps[].details.failures[].test", "leaf_name": "test", "leaf_name_norm": "test", "json_type": "string", "