-- --------------------------------------------------------------------- audit

insert into public.api_audit_events (api_id, api_name, company_name, action, actor_name, actor_user_id, details)
select id, api_name, company_name,
       case when id = '10feb4e1-16d8-4f67-8463-99d44565580d' then 'edit' else 'upload' end,
       'System migration', null,
       case when id = '10feb4e1-16d8-4f67-8463-99d44565580d'
         then 'ESS record rebuilt by migration 0041 for the SmartDocFlow eInvoicing Services API 2.0.0 (PINT A-NZ validation), which the client named on 7 October 2026 in place of the withdrawn ESS host.'
         else 'API added by migration 0041 from the SmartDocFlow eInvoicing Services API 2.0.0 document (EN 16931 validation), named by the client on 7 October 2026.'
       end
  from _0041_api;

-- ------------------------------------------------------------------ postcondition

do $$
declare
  apis_ok integer;
  schema_rows integer;
  field_rows integer;
  parameter_rows integer;
begin
  select count(*) into apis_ok from public.apis
   where id in (select id from _0041_api) and review_status = 'Published' and verified_at is null;
  select count(*) into schema_rows from public.api_schema where api_id in (select id from _0041_api);
  select count(*) into field_rows
    from public.api_schema_field f join public.api_schema s on s.id = f.schema_id
   where s.api_id in (select id from _0041_api);
  select count(*) into parameter_rows from public.api_parameter where api_id in (select id from _0041_api);
  if apis_ok <> 2 or schema_rows <> 9 or field_rows <> 82 or parameter_rows <> 0 then
    raise exception '0041 postcondition failed: % APIs, % schemas, % fields, % parameters.', apis_ok, schema_rows, field_rows, parameter_rows;
  end if;
end
$$;
